import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import {
  publishRegistryIdentity,
  setLocale,
  useAnalyticsConsent,
  trackPageview,
  type Locale,
} from "@omnicore-platform/platform-chrome";
import { ThemeProvider, useTheme } from "../theme/ThemeProvider";
import { fetchSession, type Session } from "./api";
import type { ThemeMode } from "../theme/ThemeProvider";

interface AuthState {
  session: Session | null;
  loading: boolean;
  error: string | null;
  /**
   * Optimistically merge a partial update into the in-memory session.
   * No-op when session is null (user not authenticated).
   * Callers use this to apply optimistic updates before the BFF round-trip
   * completes, and to revert on error.
   */
  mutateSession: (partial: Partial<Session>) => void;
}

// eslint-disable-next-line @typescript-eslint/no-empty-function
const noop = () => {};

const AuthContext = createContext<AuthState>({
  session: null,
  loading: true,
  error: null,
  mutateSession: noop,
});

/**
 * The 11 real BCP-47 locales supported by the platform.
 * Must mirror frontends/project.inlang/settings.json — no xx-pseudo.
 */
const REAL_LOCALES: readonly string[] = [
  "en-US",
  "en-GB",
  "en-AU",
  "ar-AE",
  "de-DE",
  "es-419",
  "fr-CA",
  "ja-JP",
  "mn-MN",
  "tl-PH",
  "zh-Hans",
] as const;

function isRealLocale(value: string): value is Locale {
  return REAL_LOCALES.includes(value);
}

function isValidTheme(value: string): value is ThemeMode {
  return value === "light" || value === "dark" || value === "system";
}

/**
 * Inner component that has access to ThemeContext (ThemeProvider wraps AuthProvider).
 * Reconciles server-side preferred_theme and preferred_locale onto the client
 * whenever the session loads or changes.
 *
 * Server wins on session load. Silent fallback on invalid stored locale.
 */
function AuthProviderInner({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>({
    session: null,
    loading: true,
    error: null,
    mutateSession: noop,
  });

  const { setMode } = useTheme();

  const mutateSession = useCallback((partial: Partial<Session>) => {
    setState((prev) => {
      if (!prev.session) return prev;
      return { ...prev, session: { ...prev.session, ...partial } };
    });
  }, []);

  useEffect(() => {
    let alive = true;
    fetchSession()
      .then((s) => {
        if (!alive) return;
        setState({ session: s, loading: false, error: null, mutateSession });
        publishRegistryIdentity(s?.user_id ?? null, s?.org_id ?? null);
      })
      .catch((e) => {
        if (!alive) return;
        setState({
          session: null,
          loading: false,
          error: String(e),
          mutateSession,
        });
        publishRegistryIdentity(null, null);
      });
    return () => {
      alive = false;
    };
  }, [mutateSession]);

  // Server-wins reconcile: when the session resolves with preferences,
  // apply them to the client theme and locale runtimes immediately.
  useEffect(() => {
    if (!state.session) return;

    const { preferred_theme, preferred_locale } = state.session;

    if (preferred_theme && isValidTheme(preferred_theme)) {
      setMode(preferred_theme);
    }

    if (preferred_locale) {
      if (isRealLocale(preferred_locale)) {
        setLocale(preferred_locale);
      } else {
        // Stale locale: server value is not in the current supported set.
        // Silent fallback — user's next explicit save will clear the stale value.
        console.warn(
          `stored preferred_locale "${preferred_locale}" not in supported set; using detected default`,
        );
      }
    }
    // Depend on user_id so this runs once per login, not on every partial mutate.
    // Also re-run if the preference fields themselves change (e.g. after a save).
  }, [
    state.session?.user_id,
    state.session?.preferred_theme,
    state.session?.preferred_locale,
    setMode,
  ]);

  // Umami tracking script: loaded from runtime config (session response),
  // never hard-coded. Both umami_host and umami_website_id must be
  // non-empty (e.g. the epic's env vars unset, or an unauthenticated
  // session, disable analytics entirely), AND consent must be explicitly
  // granted (#2236) — consent defaults to NOT granted, so with no consent
  // action taken this effect never injects anything. useAnalyticsConsent
  // re-renders this component the moment consent changes (e.g. a settings
  // toggle calls setAnalyticsConsent(true)), so granting consent after
  // the session has already resolved still loads the script without a
  // reload. Revoking consent after the script has already loaded does NOT
  // remove it or stop Umami's own auto-pageview-on-navigation behavior —
  // only this module's own track()/trackPageview() calls are consent-gated
  // per-call; the platform does not currently support retracting an
  // already-consented session's script load mid-session.
  //
  // data-auto-track="false" is required: Umami v2's script auto-tracks
  // history.pushState navigation by default, which is NOT limited to one
  // pageview on initial load — every SPA route change would otherwise
  // produce two pageview beacons (Umami's own auto one, with no org_id,
  // plus AnalyticsRouteTracker's explicit trackPageview() call), doubling
  // every count in the dashboard. Disabling auto-track also disables the
  // *initial* pageview Umami would otherwise fire on script load, so
  // script.onload fires one explicit trackPageview() for the current
  // location to cover it — AnalyticsRouteTracker's own initial-mount call
  // almost always races ahead of the deferred script's network fetch and
  // no-ops (window.umami undefined yet), so this is not a double count.
  const [analyticsConsent] = useAnalyticsConsent();
  useEffect(() => {
    if (!analyticsConsent) return;
    const host = state.session?.umami_host;
    const websiteId = state.session?.umami_website_id;
    if (!host || !websiteId) return;
    if (document.querySelector("script[data-umami-script]")) return;

    const script = document.createElement("script");
    script.defer = true;
    script.src = `${host.replace(/\/$/, "")}/script.js`;
    script.dataset.websiteId = websiteId;
    script.dataset.umamiScript = "true";
    script.dataset.autoTrack = "false";
    script.onload = () => {
      trackPageview(window.location.pathname + window.location.search);
    };
    document.head.appendChild(script);
  }, [analyticsConsent, state.session?.umami_host, state.session?.umami_website_id]);

  return <AuthContext.Provider value={state}>{children}</AuthContext.Provider>;
}

/**
 * AuthProvider bundles ThemeProvider so it is safe to render standalone
 * (e.g. in tests) without a ThemeProvider ancestor. App.tsx may wrap with its
 * own ThemeProvider — React's context nesting means the nearest provider wins,
 * so this is idempotent.
 */
export function AuthProvider({ children }: { children: ReactNode }) {
  return (
    <ThemeProvider>
      <AuthProviderInner>{children}</AuthProviderInner>
    </ThemeProvider>
  );
}

export function useAuth(): AuthState {
  return useContext(AuthContext);
}


