import { useCallback, useEffect, useState } from "react";

/**
 * TwoFAStatus enumerates the five states the AccountRoute Security card
 * can render: "loading" while the fetch is in flight, then one of three
 * terminal states reflecting the upstream IdP response, or "unavailable"
 * when the BFF returns a non-2xx (typically 503 — Keycloak Admin API down).
 */
export type TwoFAStatus =
  | "loading"
  | "enrolled"
  | "setup_required"
  | "not_configured"
  | "unavailable";

interface TwoFAResponseData {
  enrolled: boolean;
  setup_required: boolean;
}

interface EnvelopedTwoFAResponse {
  data: TwoFAResponseData;
}

/**
 * useTwoFAStatus fetches the caller's 2FA enrollment state from
 * GET /api/v1/me/2fa on mount. The returned `retry` callback re-runs the
 * fetch from the loading state — useful when the BFF surfaced an
 * `unavailable` result (e.g., Keycloak transient outage) and the user
 * wants to try again without a full page reload.
 *
 * Component-scoped — no global cache, no React Query, no provider. The
 * Security card is the only consumer in Sub-PR C.
 */
export function useTwoFAStatus(): { status: TwoFAStatus; retry: () => void } {
  const [status, setStatus] = useState<TwoFAStatus>("loading");
  const [tick, setTick] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setStatus("loading");

    fetch("/api/v1/me/2fa", { credentials: "include" })
      .then(async (r) => {
        if (cancelled) return;
        if (!r.ok) {
          setStatus("unavailable");
          return;
        }
        const body = (await r.json()) as EnvelopedTwoFAResponse;
        const data: TwoFAResponseData = body.data;
        if (data.enrolled) {
          setStatus("enrolled");
        } else if (data.setup_required) {
          setStatus("setup_required");
        } else {
          setStatus("not_configured");
        }
      })
      .catch(() => {
        if (!cancelled) setStatus("unavailable");
      });

    return () => {
      cancelled = true;
    };
  }, [tick]);

  const retry = useCallback(() => {
    setTick((t) => t + 1);
  }, []);

  return { status, retry };
}


