import { useCallback } from "react";
import {
  switchWorkspace,
  useWorkspaceList,
  WorkspaceApiError,
} from "@omnicore-platform/platform-chrome";
import { toast } from "../lib/toast";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

/**
 * useWorkspaceSwitch — shared workspace-switch handler for shell-mfe routes
 * that mount the Topbar. Returns a stable callback that:
 *
 *   - Calls switchWorkspace(orgId).
 *   - On success, reloads the page so the new tenant context propagates
 *     through AuthProvider, useWorkspaceList, and every downstream fetch.
 *   - On WorkspaceApiError with code "workspace_not_accessible", refetches
 *     the workspace list and shows a localized error toast.
 *   - On any other error, shows the generic switch-failed toast.
 *
 * Designed as a hook (not a plain function) so callers don't have to wire
 * useWorkspaceList themselves — the hook owns that subscription. The
 * returned callback's identity is stable across renders so consumers can
 * pass it to <Topbar onSwitchWorkspace={...}> without prop churn.
 */
export function useWorkspaceSwitch(): (orgId: string) => Promise<void> {
  const { refetch: refetchWorkspaces } = useWorkspaceList();

  return useCallback(
    async (orgId: string): Promise<void> => {
      try {
        await switchWorkspace(orgId);
        window.location.reload();
      } catch (err) {
        if (
          err instanceof WorkspaceApiError &&
          err.code === "workspace_not_accessible"
        ) {
          await refetchWorkspaces();
          toast.error(m.common_workspace_no_access_error());
        } else {
          toast.error(m.common_workspace_switch_failed_error());
        }
      }
    },
    [refetchWorkspaces],
  );
}



