/**
 * RequireAuth — gate wrapper for routes that require a valid session.
 *
 * When the auth state resolves to "no session", redirects to /login with
 * the user's current path encoded as `return_to`. Without this gate, a
 * stale or absent session cookie causes useMfeRegistry to 401 silently
 * (registry stays empty → MfeLoader renders null → blank screen).
 *
 * Pairs with the in-MFE 401 handlers, which catch mid-session expiry
 * after the MFE has already mounted. This gate handles the initial-load
 * case.
 */

import { type ReactElement, type ReactNode } from "react";
import { Navigate, useLocation } from "react-router-dom";
import { useAuth } from "./AuthProvider";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

interface RequireAuthProps {
  children: ReactNode;
}

export function RequireAuth({ children }: RequireAuthProps): ReactElement {
  // Subscribe so Paraglide m.* calls re-render on locale change.
  useLocale();
  const { session, loading } = useAuth();
  const location = useLocation();

  if (loading) {
    return (
      <div
        role="status"
        aria-live="polite"
        className="flex min-h-screen items-center justify-center bg-cog-canvas text-cog-text-secondary"
      >
        {m.common_loading()}
      </div>
    );
  }

  if (!session) {
    const returnTo = location.pathname + location.search;
    return (
      <Navigate
        to={`/login?return_to=${encodeURIComponent(returnTo)}`}
        replace
      />
    );
  }

  return <>{children}</>;
}


