export interface Session {
  user_id: string;
  org_id: string;
  roles: string[];
  email: string;
  display_name?: string;
  /** Absolute URL to the IdP's account console (Keycloak Account
   *  Console at `${issuer}/account`). Empty string when the issuer
   *  is unset (dev / unit-test envs). When empty the Manage
   *  password / 2FA button on /account is omitted. */
  account_console_url: string;
  /**
   * Server-persisted theme preference. One of "light" | "dark" | "system".
   * Absent / empty string means "unset; client decides default".
   */
  preferred_theme?: string;
  /**
   * Server-persisted locale preference. BCP-47 code from the 11 supported
   * real locales. Absent / empty string means "unset; client detects".
   */
  preferred_locale?: string;
  /**
   * The caller's org-membership role at the org root, resolved by shell-bff
   * from org-svc VerifyMembership. One of "OWNER" | "ADMIN" | "MEMBER" |
   * "VIEWER". Empty string (or absent) when the user has no org-root
   * membership (e.g. platform admins) — fail-closed. Gates the /organization
   * settings surface (OWNER/ADMIN only).
   */
  org_role?: string;
  /**
   * Base URL to load the Umami tracking script from (e.g.
   * "http://umami.localhost"). Absent/empty means analytics is disabled —
   * the shell must not load the script unless both this and
   * `umami_website_id` are non-empty. See epic #2231.
   */
  umami_host?: string;
  /** Umami website-id (UUID) stamped on the script's data-website-id. */
  umami_website_id?: string;
}

export async function fetchSession(): Promise<Session | null> {
  const r = await fetch("/api/v1/session", { credentials: "include" });
  if (r.status === 401 || r.status === 403) return null;
  if (!r.ok) throw new Error(`session fetch failed: ${r.status}`);
  const body = await r.json();
  return body.data as Session;
}

export function loginRedirect(returnTo: string = "/"): void {
  window.location.href = `/api/v1/auth/login?return_to=${encodeURIComponent(returnTo)}`;
}

export function logout(): void {
  // Full navigation to /api/v1/auth/logout (GET): the BFF clears its
  // session cookie, then 302-redirects to Keycloak's end_session endpoint.
  // Keycloak terminates its own session and 302-redirects back to /login.
  // POST-logout would only clear the BFF cookie, leaving Keycloak's SSO
  // cookie intact — clicking Sign in afterwards would silently re-auth.
  window.location.href = "/api/v1/auth/logout";
}

/**
 * Payload for PATCH /api/v1/me.
 * All fields are optional — only the keys present in the object are sent.
 * The BFF treats absent keys as "no change" and empty strings as "clear to NULL".
 *
 * IMPORTANT: do not send `preferred_locale: "xx-pseudo"` — the server CHECK
 * constraint rejects that value; validate with isRealLocale before calling.
 */
export interface UpdateMePayload {
  display_name?: string;
  preferred_theme?: string;
  preferred_locale?: string;
}

/**
 * Subset of Session returned by PATCH /api/v1/me.
 * The BFF only echoes the mutable user fields — account_console_url is
 * not included in the update response, so we return only what the
 * server actually sends rather than pretending to return a full Session.
 */
export type MeUpdateResult = Pick<
  Session,
  | "user_id"
  | "org_id"
  | "email"
  | "display_name"
  | "roles"
  | "preferred_theme"
  | "preferred_locale"
>;

/**
 * The 7 in-app notification kinds the platform supports.
 * Values are lowercase wire strings as returned by the BFF's
 * `notificationKindString` helper (strips NOTIFICATION_KIND_ prefix + lowercases).
 */
export type NotificationKind =
  | "invite_accepted"
  | "membership_added"
  | "workspace_switched"
  | "ingest_completed"
  | "ingest_failed"
  | "role_changed"
  | "login_new_device";

/**
 * A record mapping every known NotificationKind to an enabled/disabled boolean.
 * All 7 keys are always present — the BFF fills defaults (true) for unset rows.
 */
export type NotificationPreferences = Record<NotificationKind, boolean>;

/**
 * Fetch the calling user's per-kind notification preferences.
 * Returns a Record keyed on the 7 NotificationKind values.
 * Throws on non-2xx responses.
 */
export async function getNotificationPreferences(): Promise<NotificationPreferences> {
  const r = await fetch("/api/v1/me/notifications/preferences", {
    credentials: "include",
  });
  if (!r.ok) throw new Error(`fetch notification preferences failed: ${r.status}`);
  const body = (await r.json()) as {
    data: { preferences: Array<{ kind: string; enabled: boolean }> };
  };
  // BFF returns an array; convert to Record for ergonomic local state.
  const prefs = {} as NotificationPreferences;
  for (const { kind, enabled } of body.data.preferences) {
    prefs[kind as NotificationKind] = enabled;
  }
  return prefs;
}

/**
 * Persist the calling user's full preference set.
 * Sends the full record as an array (BFF expects all 7 entries).
 * Returns the canonical server post-image.
 * Throws on non-2xx responses.
 */
export async function setNotificationPreferences(
  prefs: NotificationPreferences,
): Promise<NotificationPreferences> {
  const preferences = (Object.keys(prefs) as NotificationKind[]).map((kind) => ({
    kind,
    enabled: prefs[kind],
  }));
  const r = await fetch("/api/v1/me/notifications/preferences", {
    method: "PUT",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ preferences }),
  });
  if (!r.ok) throw new Error(`set notification preferences failed: ${r.status}`);
  const body = (await r.json()) as {
    data: { preferences: Array<{ kind: string; enabled: boolean }> };
  };
  const updated = {} as NotificationPreferences;
  for (const { kind, enabled } of body.data.preferences) {
    updated[kind as NotificationKind] = enabled;
  }
  return updated;
}

/**
 * updateMe sends PATCH /api/v1/me to the BFF with the caller's chosen fields.
 * Accepts a payload object so callers can pass display_name, preferred_theme,
 * and/or preferred_locale independently — only the keys provided are sent.
 *
 * Returns the server's canonical post-image of the updated fields.
 * Throws on non-2xx responses; the error.message contains the server's
 * `error.message` field when present (e.g., "display_name too long").
 *
 * Backwards-compat: existing callers that passed `{display_name}` continue
 * to work unchanged.
 */
export async function updateMe(payload: UpdateMePayload): Promise<MeUpdateResult> {
  const r = await fetch("/api/v1/me", {
    method: "PATCH",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!r.ok) {
    const errBody = await r
      .json()
      .catch(() => ({}) as { error?: { message?: string } });
    const msg =
      (errBody as { error?: { message?: string } }).error?.message ??
      `me update failed: ${r.status}`;
    throw new Error(msg);
  }
  const body = (await r.json()) as {
    data: { user: MeUpdateResult };
  };
  return body.data.user;
}


