import { useCallback } from "react";
import { useNavigate } from "react-router-dom";

/**
 * useTopbarNavHandlers — shared navigation callbacks for shell-mfe routes
 * that mount the Topbar. Returns stable callbacks for the two in-app nav
 * targets the Topbar exposes:
 *
 *   - handleProfile → navigate("/profile")
 *   - handleAccountSettings → navigate("/account")
 *
 * Centralising these removes duplicated inline arrow props from each route
 * and ensures the navigation logic is covered once in the auth test suite
 * rather than being an untested inline arrow in every route.
 *
 * Callback identities are stable (useCallback + [navigate] dep) so consumers
 * can pass them to <Topbar onProfile={...} onAccountSettings={...}> without
 * prop churn.
 */
export function useTopbarNavHandlers(): {
  handleProfile: () => void;
  handleAccountSettings: () => void;
} {
  const navigate = useNavigate();

  const handleProfile = useCallback(() => {
    navigate("/profile");
  }, [navigate]);

  const handleAccountSettings = useCallback(() => {
    navigate("/account");
  }, [navigate]);

  return { handleProfile, handleAccountSettings };
}


